contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint balanceBefore = address(this).balance;

        // play() must never revert, so no try/catch is needed; if it reverts the test fails.
        c.play{value: amount}(); if (__ESBMC_reverted()) return;

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(this).balance;

        // General rule: play() always completes; if no payout occurred, potAfter == amount,
        // and if a payout occurred (test received Ether), potAfter == 0.
        assert(potAfter == amount || (potAfter == 0 && balanceAfter > balanceBefore - amount));
    }

    receive() external payable {}
}

